config.script:
function sleep(ms){return new Promise(function(r){setTimeout(r,ms);});}
function visible(el){
  if(!el)return false;
  var r=el.getBoundingClientRect();
  if(r.width<=0||r.height<=0)return false;
  var s=getComputedStyle(el);
  return s.visibility!=='hidden'&&s.display!=='none'&&s.opacity!=='0';
}
function pick(sel){
  var list=document.querySelectorAll(sel);
  for(var i=0;i<list.length;i++){if(visible(list[i]))return list[i];}
  return null;
}
function text(el){return el?(el.innerText||'').replace(/\s+/g,' ').trim():'';}
// Riot has already renamed this control once (data-testid signin-cta ->
// cta-primary), so match it by ROLE + LABEL instead of trusting a testid, and
// look inside the product-registration blade FIRST so the RiotBar's own global
// "Sign In" (which opens an RSO modal, not this flow) can never win.
function findSignIn(){
  var scopes=[document.querySelector('[data-testid="product-registration"]'),document.body];
  var sels=['[data-testid="signin-cta"]','[data-testid="cta-primary"]','a[role="button"]','button','[role="button"]'];
  for(var s=0;s<scopes.length;s++){
    if(!scopes[s])continue;
    for(var q=0;q<sels.length;q++){
      var list=scopes[s].querySelectorAll(sels[q]);
      for(var i=0;i<list.length;i++){
        var el=list[i];
        if(!visible(el))continue;
        // SUBSTRING, not an exact match: the blade's control reads
        // "SIGN IN TO REGISTER", while the RiotBar's says just "Sign In".
        if(/(sign|log)[ -]?in/i.test(text(el)))return el;
      }
    }
  }
  return null;
}
for(var i=0;i<24;i++){
  if(document.querySelector('[data-testid="product-selection-card"][data-state="registered"]')||
     pick('[data-testid="success-primary-cta"]'))return 'registered';
  var et=text(pick('[data-testid="register-error-type"]'));
  if(et)return 'error:'+et.slice(0,160);
  var ec=text(pick('[data-testid="registration-error-container"]'));
  if(ec)return 'error:'+ec.slice(0,160);
  if(pick('[data-testid="register-cta"]'))return 'active';
  if(findSignIn())return 'unauth';
  // Outside its window the blade renders REGISTRATION_CLOSED / _PENDING: prose,
  // no register CTA, no sign-in. Checked AFTER the working states so a healthy
  // page can never reach it. Fail fast instead of polling for 90s.
  var blade=text(document.querySelector('[data-testid="product-registration"]'));
  if(/registration is closed|no longer accepting|has (now )?ended|closed for entries|check back/i.test(blade))
    return 'error:'+blade.slice(0,160);
  await sleep(500);
}
// Nothing recognisable. Carry what the blade actually says so the failure names
// the real state (closed, pending, geo-blocked) instead of "never became ready".
return 'idle:'+text(document.querySelector('[data-testid="product-registration"]')).slice(0,160);

