for(var i=0;i<24;i++){
  var host=location.hostname;
  if(host.indexOf('playriftbound.com')!==-1&&host.indexOf('xsso.')===-1)return 'registration';
  var err=pick('[data-testid="error-message"], [data-testid="error-text"]');
  var msg=text(err);
  if(msg)return 'error:'+msg.slice(0,160);
  // A form that is still on screen is only actionable while it is EMPTY. Riot
  // leaves both forms mounted with their values while the submit is in flight,
  // so reporting 'mfa'/'login' on sight would re-submit the credentials and -
  // worse - go wait for a second OTP email that Riot never sends.
  var boxes=document.querySelectorAll('[data-testid="input-mfa"] input, input[data-testid="input-mfa"]');
  if(boxes.length){
    var typed=0;
    for(var b=0;b<boxes.length;b++){if((boxes[b].value||'').length)typed++;}
    return typed?'wait':'mfa';
  }
  var frames=document.querySelectorAll('iframe[src*="hcaptcha.com"]');
  for(var f=0;f<frames.length;f++){
    if(visible(frames[f])&&/challenge/i.test(frames[f].title||''))return 'captcha';
  }
  var user=pick('input[data-testid="input-username"], [data-testid="input-username"] input, input[name="username"]');
  if(user)return (user.value||'').trim()==='{{account.username}}'?'wait':'login';
  await sleep(500);
}
return 'wait';

/* card state after the product click */
for(var i=0;i<10;i++){
  if(document.querySelector('[data-testid="product-selection-card"][data-state="selected"]'))return '1';
  await new Promise(function(r){setTimeout(r,300);});
}
return '0';

